let likes=read('gh24-likes',{});let replyTo=null;
function arrangeComments(all,sort,likeState){
 const byId=new Map(all.map(c=>[c.id,c])),children=new Map(),roots=[];
 all.forEach(c=>{if(c.parentId&&c.parentId!==c.id&&byId.has(c.parentId)){if(!children.has(c.parentId))children.set(c.parentId,[]);children.get(c.parentId).push(c);}else roots.push(c);});
 if(sort==='best')roots.sort((a,b)=>(b.likes+(likeState[b.id]?1:0))-(a.likes+(likeState[a.id]?1:0)));
 if(sort==='new')roots.reverse();
 const pinnedIds=['b1','b10'],pinned=pinnedIds.map(id=>roots.find(c=>c.id===id)).filter(Boolean);
 const result=[],seen=new Set();
 function append(c,depth,pinned){if(seen.has(c.id))return;seen.add(c.id);result.push({...c,reply:depth>0,pinned});(children.get(c.id)||[]).forEach(child=>append(child,depth+1,pinned));}
 pinned.concat(roots.filter(c=>!pinnedIds.includes(c.id))).forEach(c=>append(c,0,pinnedIds.includes(c.id)));
 all.forEach(c=>{if(!seen.has(c.id))append(c,0,false);});
 return result;
}
